using FacialPresets;
using System.Text.Json;
namespace DanceStudio;
public static class FacialEdits {
 public static FacialSegment Copy(FacialSegment c)=>JsonSerializer.Deserialize<FacialSegment>(JsonSerializer.Serialize(c))!;
 public static void Timing(FacialSegment to,FacialSegment from){to.Start=from.Start;to.End=from.End;to.SourceOffset=from.SourceOffset;to.EnvelopeOffset=from.EnvelopeOffset;to.EnvelopeDuration=from.EnvelopeDuration;to.StrengthCurve=from.StrengthCurve==null?null:System.Text.Json.JsonSerializer.Deserialize<List<StrengthPoint>>(System.Text.Json.JsonSerializer.Serialize(from.StrengthCurve));}
 public static FacialSegment Resize(FacialSegment original,int edge,double delta){var c=Copy(original);double a=original.Start,b=original.End;if(edge<0){double min=c.Clip==null?0:Math.Max(0,a-c.SourceOffset/c.PlaybackSpeed);c.Start=Math.Clamp(a+delta,min,b-.001);if(c.Clip!=null)c.SourceOffset+=(c.Start-a)*c.PlaybackSpeed;}else{double max=c.Clip==null?ProjectRules.MaxProjectTime:Math.Min(ProjectRules.MaxProjectTime,a+(c.Clip.Duration-c.SourceOffset)/c.PlaybackSpeed);c.End=Math.Clamp(b+delta,a+.001,max);}double origin=a-original.EnvelopeOffset,finish=origin+(original.EnvelopeDuration??b-a);origin=Math.Min(origin,c.Start);finish=Math.Max(finish,c.End);if(c.StrengthCurve!=null){double shift=a-original.EnvelopeOffset-origin;foreach(var point in c.StrengthCurve)point.Time+=shift;}c.EnvelopeOffset=c.Start-origin;c.EnvelopeDuration=finish-origin;return c;}
 public static bool Move(List<FacialSegment> all,IReadOnlyList<FacialSegment> originals,double delta){if(originals.Count==0)return false;delta=Math.Clamp(delta,-originals.Min(c=>c.Start),ProjectRules.MaxProjectTime-originals.Max(c=>c.End));var ids=originals.Select(c=>c.Id).ToHashSet();var next=all.Select(Copy).ToList();foreach(var old in originals){var c=next.Single(c=>c.Id==old.Id);c.Start=old.Start+delta;c.End=old.End+delta;}try{FacialTimeline.Validate(next);}catch(System.IO.InvalidDataException){return false;}foreach(var c in all.Where(c=>ids.Contains(c.Id)))Timing(c,next.Single(n=>n.Id==c.Id));return true;}
 public static List<FacialSegment> Placement(Preset? p,FacialClip? clip,double time){if(!double.IsFinite(time)||time<0)throw new System.IO.InvalidDataException("Invalid placement time");var channels=clip==null?p!.Channels.Where(c=>c.Value.Morphs.Count>0).Select(c=>c.Key):clip.Keys.SelectMany(k=>k.State.Channels.Where(c=>c.Value.Morphs.Count>0).Select(c=>c.Key));var result=channels.Distinct().Select(ch=>new FacialSegment{Start=time,End=time+(clip?.Duration??1),Channel=ch,Preset=p==null?new():FacialTimeline.Copy(p),Clip=clip==null?null:JsonSerializer.Deserialize<FacialClip>(JsonSerializer.Serialize(clip))}).ToList();if(result.Count==0)throw new System.IO.InvalidDataException(UiText.T("libNoChannels"));return result;}
}
